 $('start').textContent=phase==='STARTING'?'Starting…':phase==='STOPPING'?'Stopping…':phase==='WAITING FOR DATA'?'Waiting for data…':active?'● Survey running':phase==='FAILED'?'↻ Retry survey':'▶ Start survey';
